# 自定义
def panduan1(data,a,x):
    strn = ''
    for i in [a]:
        try:
            len(data[f'{i}'][x]) # 获取该列中对应行的数据项的长度
            strn = strn + str(data[f'{i}'][x]) # 将该数据项转换为字符串并添加到 strn 中
        except:
            strn = strn+strn # 空字符串
    return strn
